import Foundation
import Testing
@testable import LHAPI

/// tests/fixtures/native/*.json at the repository root — generated by
/// scripts/export-native-fixtures.ts from the server's own projection.
enum Fixtures {
	static let directory: URL = URL(fileURLWithPath: #filePath)
		.deletingLastPathComponent() // LHAPITests
		.deletingLastPathComponent() // Tests
		.deletingLastPathComponent() // LHKit
		.deletingLastPathComponent() // ios
		.deletingLastPathComponent() // repository root
		.appending(path: "tests/fixtures/native")

	static func data(_ name: String) throws -> Data {
		try Data(contentsOf: directory.appending(path: name))
	}

	static var viewNames: [String] {
		(try? FileManager.default.contentsOfDirectory(atPath: directory.path(percentEncoded: false)))?
			.filter { $0.hasSuffix(".view.json") }.sorted() ?? []
	}
}

@Suite("Native contract fixtures")
struct FixtureTests {
	@Test func fixturesExist() {
		#expect(Fixtures.viewNames.count >= 3, "run scripts/export-native-fixtures.ts")
	}

	@Test(arguments: Fixtures.viewNames)
	func decodesEveryView(name: String) throws {
		let view = try JSONDecoder().decode(NativeSessionView.self, from: Fixtures.data(name))
		#expect(view.state.version == 1)
		#expect(!view.chatId.isEmpty)
		#expect(view.messages.allSatisfy { !$0.id.isEmpty })
		// Round trip: what the cache writes decodes to the same value.
		let again = try JSONDecoder().decode(NativeSessionView.self, from: JSONEncoder().encode(view))
		#expect(again == view)
	}

	@Test func pendingQuizDock() throws {
		let view = try JSONDecoder().decode(NativeSessionView.self, from: Fixtures.data("pending-quiz.view.json"))
		guard case .question(let dock) = view.state.dock else {
			Issue.record("expected a question dock")
			return
		}
		#expect(dock.toolCallId == "call-1")
		#expect(dock.kind == "quiz")
		#expect(dock.mode == .singleSelect)
		#expect(Set(dock.options.map(\.value)) == ["Venus", "Mercury", "Mars"])
		#expect(dock.confidenceStops == [0, 30, 50, 70, 90, 100])
		#expect(view.state.status == .idle)
		#expect(view.state.kind == .teach)
	}

	@Test func practiceViewKnowsItsKind() throws {
		let name = try #require(Fixtures.viewNames.first { name in
			(try? JSONDecoder().decode(NativeSessionView.self, from: Fixtures.data(name)))?.state.kind == .practice
		})
		let view = try JSONDecoder().decode(NativeSessionView.self, from: Fixtures.data(name))
		#expect(view.state.phase == nil)
		let partTypes = Set(view.messages.flatMap { $0.parts.map(\.type) })
		#expect(partTypes.contains("tool-problem"))
	}

	@Test func streamFramesReduceToTheSettledView() throws {
		let frames = try JSONDecoder().decode([NativeStreamFrame].self, from: Fixtures.data("stream-frames.json"))
		#expect(frames.count == 3)
		var view: NativeSessionView?
		for frame in frames.dropLast() { view = NativeViewReducer.apply(frame, to: view) }
		guard case .settled(let settled) = frames.last else {
			Issue.record("last frame must be settled")
			return
		}
		let patched = try #require(view)
		#expect(patched.messages == settled.messages)
		#expect(patched.state.dock == settled.state.dock)
		#expect(NativeViewReducer.apply(frames[1], to: nil) == nil, "a patch without a base asks for a resync")
	}
}
